			return fmt.Errorf("scan range: %w", err)
		}
		affected := vuln.Range{}
		if lower.Valid {
			text := lower.String
			included := lowerInclude == 1
			affected.Lower = &text
			affected.LowerInclude = &included
		}
		if upper.Valid {
			text := upper.String
			included := upperInclude == 1
			affected.Upper = &text
