	SeverityLow,
	SeverityMedium,
	SeverityHigh,
	SeverityCritical,
}

// Statuses lists every disposition status accepted on registration and update.
var Statuses = []Status{
	StatusOpen,
	StatusInProgress,
	StatusFixed,
	StatusWontFix,
	StatusAccepted,
}

